From 0ac70bd768a1c27e9e1bdb37c228a81fc35f634c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:22:18 +0100
Subject: [PATCH] libs/editor: round connection speed and hide it when unknown

NetworkManager reports the speed in kbit/s, but values below 1000 were
labelled Bit/s and the rest was printed unrounded, as in 1.2009 GBit/s.
Use the right unit, round the speed, and skip the row when it's zero.

BUG: 481301
---
 libs/editor/connectiondetails.cpp | 4 ++--
 libs/editor/uiutils.cpp           | 6 +++---
 libs/editor/uiutils.h             | 2 +-
 3 files changed, 6 insertions(+), 6 deletions(-)

diff --git a/libs/editor/connectiondetails.cpp b/libs/editor/connectiondetails.cpp
index d030b16d9..09ffe6ce9 100644
--- a/libs/editor/connectiondetails.cpp
+++ b/libs/editor/connectiondetails.cpp
@@ -87,7 +87,7 @@ getConnectionDetails(const NetworkManager::Connection::Ptr &connection, const Ne
         QList<QPair<QString, QString>> details;
         NetworkManager::WiredDevice::Ptr wiredDevice = device.objectCast<NetworkManager::WiredDevice>();
         if (wiredDevice) {
-            if (isConnectionActive) {
+            if (isConnectionActive && wiredDevice->bitRate() > 0) {
                 details.append({i18n("Connection speed"), UiUtils::connectionSpeed(wiredDevice->bitRate())});
             }
             details.append({i18n("MAC Address"), wiredDevice->hardwareAddress()});
@@ -151,7 +151,7 @@ getConnectionDetails(const NetworkManager::Connection::Ptr &connection, const Ne
         }

         if (wirelessDevice) {
-            if (isConnectionActive) {
+            if (isConnectionActive && wirelessDevice->bitRate() > 0) {
                 details.append({i18n("Connection Speed"), UiUtils::connectionSpeed(wirelessDevice->bitRate())});
             }

diff --git a/libs/editor/uiutils.cpp b/libs/editor/uiutils.cpp
index ba42f2d8b..e93bc4efd 100644
--- a/libs/editor/uiutils.cpp
+++ b/libs/editor/uiutils.cpp
@@ -431,11 +431,11 @@ QString UiUtils::connectionSpeed(double bitrate)
 {
     QString out;
     if (bitrate < 1000) {
-        out = i18nc("connection speed", "%1 Bit/s", bitrate);
+        out = i18nc("connection speed", "%1 kBit/s", bitrate);
     } else if (bitrate < 1000000) {
-        out = i18nc("connection speed", "%1 MBit/s", bitrate / 1000);
+        out = i18nc("connection speed", "%1 MBit/s", qRound(bitrate / 1000));
     } else {
-        out = i18nc("connection speed", "%1 GBit/s", bitrate / 1000000);
+        out = ki18nc("connection speed", "%1 GBit/s").subs(bitrate / 1000000, 0, 'g', 3).toString();
     }
     return out;
 }
diff --git a/libs/editor/uiutils.h b/libs/editor/uiutils.h
index 290118cad..4d2da7fe0 100644
--- a/libs/editor/uiutils.h
+++ b/libs/editor/uiutils.h
@@ -100,7 +100,7 @@ public:

     /**
      * @return localized string showing a human-readable connection speed. 1000 is used as base.
-     * @param bitrate bitrate of the connection per second
+     * @param bitrate bitrate of the connection in kbit/s
      */
     static QString connectionSpeed(double bitrate);

-- 
